'use client';

import { ArrowDown, ArrowUp, ChevronsUpDown } from 'lucide-react';

// @interlace/ranking v1.0.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/ranking
// What changed since: https://ds.interlace.tools/c/ranking#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — RankChoices and RankResults
 *
 * A room ranks the same items by preference. `RankChoices` is a phone: the
 * items in a seeded starting order (so nobody's first item is favoured by
 * where it was printed), moved with up and down buttons or the arrow keys
 * on each row's handle, then sent. `RankResults` is the screen: the room's
 * order with each item's average place and first-place count, gliding as
 * answers arrive. For a round with a right order, use `OrderGame`.
 *
 * ## Anatomy
 *
 *   RankChoices                    (div — data-slot="rank-choices", data-state=ranking|sent)
 *     ├─ p                         (data-slot="rank-choices-question", labels the list)
 *     ├─ ol (FlipGroup)            (data-slot="rank-choices-list")
 *     │   └─ li × n                (place, handle button (arrow keys), label, up / down)
 *     ├─ Button                    (data-slot="rank-choices-send")
 *     └─ span sr-only aria-live    (data-slot="rank-choices-announce": "Music, now 2 of 4")
 *   RankResults                    (FlipGroup ol — data-slot="rank-results")
 *     └─ li × n                    (place, label, bar, average place; read as one line)
 *
 * ## Motion
 *
 * A moved row and its neighbour glide (FlipGroup, 250ms); room rows glide
 * to their new places as answers arrive. Under reduced motion they jump.
 *
 * ## MIN_VIEWPORT — 320
 *
 * | Rule | Concept                   | Where in this file                                   |
 * | ---- | ------------------------- | ---------------------------------------------------- |
 * | R4   | Extends native el         | `div` props                                          |
 * | R6   | data-slot per part        | rank-choices / -question / -list / -send / -announce; rank-results |
 * | R7   | cn + ...rest              | `cn(…, className)` + `{...props}`                    |
 * | R9   | Controlled + uncontrolled | `order` / `defaultOrder` / `onOrderChange` / `onSend` |
 * | R14  | Declares min viewport     | `data-min-viewport` + exported const                 |
 * | R26  | A11y                      | moves by button or key, each announced; results read as one line per row |
 */

import * as React from 'react';

import { FlipGroup } from '@/components/ui/effects/flip-group';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { seededShuffle } from '@/components/ui/games/daily';
import { moveItem } from '@/components/ui/games/order-model';
import type { RankedItem } from '@/components/ui/games/ranking-model';

export const MIN_VIEWPORT = 320 as const;

interface RankOption {
  id: string;
  label: string;
}

interface RankChoicesLabels {
  /** @default (label) => `Move ${label} up` */
  up?: (label: string) => string;
  /** @default (label) => `Move ${label} down` */
  down?: (label: string) => string;
  /** The handle's name. @default (label, place, total) => `${label}, ${place} of ${total}. Use the arrow keys to move it.` */
  handle?: (label: string, place: number, total: number) => string;
  /** Announced after a move. @default (label, place, total) => `${label}, now ${place} of ${total}` */
  moved?: (label: string, place: number, total: number) => string;
  /** @default 'Send my order' */
  send?: string;
  /** @default 'Sent. Thank you.' */
  sent?: string;
}

type RankChoicesProps = Omit<React.ComponentProps<'div'>, 'children'> & {
  question: React.ReactNode;
  options: readonly RankOption[];
  /** Seeds the starting order. @default the ids joined */
  seed?: number | string;
  order?: readonly string[];
  defaultOrder?: readonly string[];
  onOrderChange?: (order: string[]) => void;
  /** Called once, with the order. */
  onSend?: (order: string[]) => void;
  /** Shown as sent, from the parent. */
  sent?: boolean;
  labels?: RankChoicesLabels;
};

function RankChoices({
  question,
  options,
  seed,
  order: orderProp,
  defaultOrder,
  onOrderChange,
  onSend,
  sent: sentProp,
  labels,
  className,
  ...props
}: RankChoicesProps) {
  const ids = options.map((o) => o.id);
  const [own, setOwn] = React.useState<readonly string[]>(
    () => defaultOrder ?? seededShuffle(ids, seed ?? ids.join('|')),
  );
  const order = orderProp ?? own;
  const [sentHere, setSentHere] = React.useState(false);
  const sent = sentProp ?? sentHere;
  const [announce, setAnnounce] = React.useState('');
  const questionId = React.useId();
  const names = new Map(options.map((o) => [o.id, o.label]));
  const rootRef = React.useRef<HTMLDivElement>(null);
  const total = order.length;

  const move = (from: number, to: number, focusHandle: boolean) => {
    if (sent || to < 0 || to >= total || from === to) return;
    const next = moveItem(order, from, to);
    const id = order[from] as string;
    if (orderProp === undefined) setOwn(next);
    onOrderChange?.(next);
    setAnnounce(
      (labels?.moved ?? ((l: string, p: number, t: number) => `${l}, now ${p} of ${t}`))(
        names.get(id) ?? id,
        to + 1,
        total,
      ),
    );
    if (focusHandle) {
      // Keep focus on the moved row's handle after the DOM reorders.
      queueMicrotask(() =>
        [...(rootRef.current?.querySelectorAll<HTMLElement>('[data-handle]') ?? [])]
          .find((el) => el.dataset.handle === id)
          ?.focus(),
      );
    }
  };

  const onKey = (e: React.KeyboardEvent, i: number) => {
    const to =
      e.key === 'ArrowUp'
        ? i - 1
        : e.key === 'ArrowDown'
          ? i + 1
          : e.key === 'Home'
            ? 0
            : e.key === 'End'
              ? total - 1
              : null;
    if (to === null) return;
    e.preventDefault();
    move(i, to, true);
  };

  return (
    <div
      ref={rootRef}
      data-slot="rank-choices"
      data-state={sent ? 'sent' : 'ranking'}
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn('grid gap-4', className)}
      {...props}
    >
      <p id={questionId} data-slot="rank-choices-question" className="font-heading text-lg font-semibold text-balance">
        {question}
      </p>
      <FlipGroup
        render={<ol />}
        duration={250}
        aria-labelledby={questionId}
        data-slot="rank-choices-list"
        className="grid gap-2"
      >
        {order.map((id, i) => {
          const label = names.get(id) ?? id;
          return (
            <li key={id} data-flip-id={id} className="bg-card flex items-center gap-2 rounded-lg border p-2 ps-3">
              <span aria-hidden className="text-muted-foreground w-5 text-sm font-semibold tabular-nums">
                {i + 1}
              </span>
              <button
                type="button"
                data-handle={id}
                disabled={sent}
                aria-label={(
                  labels?.handle ??
                  ((l: string, p: number, t: number) => `${l}, ${p} of ${t}. Use the arrow keys to move it.`)
                )(label, i + 1, total)}
                onKeyDown={(e) => onKey(e, i)}
                className="text-muted-foreground focus-visible:outline-ring grid size-8 place-items-center rounded-md outline-offset-2 focus-visible:outline-2 disabled:opacity-50"
              >
                <ChevronsUpDown aria-hidden className="size-4" />
              </button>
              <span className="min-w-0 flex-1 text-sm font-medium">{label}</span>
              <Button
                size="icon-sm"
                variant="ghost"
                aria-label={(labels?.up ?? ((l: string) => `Move ${l} up`))(label)}
                disabled={sent || i === 0}
                onClick={() => move(i, i - 1, false)}
              >
                <ArrowUp aria-hidden />
              </Button>
              <Button
                size="icon-sm"
                variant="ghost"
                aria-label={(labels?.down ?? ((l: string) => `Move ${l} down`))(label)}
                disabled={sent || i === total - 1}
                onClick={() => move(i, i + 1, false)}
              >
                <ArrowDown aria-hidden />
              </Button>
            </li>
          );
        })}
      </FlipGroup>
      {sent ? (
        <p className="text-muted-foreground text-sm">{labels?.sent ?? 'Sent. Thank you.'}</p>
      ) : (
        <Button
          data-slot="rank-choices-send"
          size="lg"
          className="justify-self-start"
          onClick={() => {
            setSentHere(true);
            onSend?.([...order]);
          }}
        >
          {labels?.send ?? 'Send my order'}
        </Button>
      )}
      <span data-slot="rank-choices-announce" aria-live="polite" className="sr-only">
        {announce}
      </span>
    </div>
  );
}
RankChoices.displayName = 'RankChoices';

// --- RankResults (screen) --------------------------------------------------------

interface RankResultsLabels {
  /** One row, read whole. @default English: 'Music: place 1, average place 1.8, first for 4 people' */
  row?: (r: { place: number; label: string; mean: string; firsts: string }) => string;
  /** The visible average. @default (mean) => `avg ${mean}` */
  mean?: (mean: string) => string;
}

type RankResultsProps = Omit<React.ComponentProps<'div'>, 'children'> & {
  /** From `tallyRankings`. */
  items: readonly RankedItem[];
  options: readonly RankOption[];
  /** `stage` for a shared screen. @default 'default' */
  size?: 'default' | 'stage';
  locale?: string;
  labels?: RankResultsLabels;
};

function RankResults({ items, options, size = 'default', locale, labels, className, ...props }: RankResultsProps) {
  const one = React.useMemo(() => new Intl.NumberFormat(locale, { maximumFractionDigits: 1 }), [locale]);
  const nf = React.useMemo(() => new Intl.NumberFormat(locale), [locale]);
  const names = new Map(options.map((o) => [o.id, o.label]));
  const top = Math.max(...items.map((r) => r.points), 1);
  const stage = size === 'stage';
  return (
    <FlipGroup
      render={<ol />}
      data-slot="rank-results"
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn('grid gap-3', className)}
      {...props}
    >
      {items.map((r, i) => {
        const label = names.get(r.id) ?? r.id;
        const mean = one.format(r.meanPlace);
        const firsts = nf.format(r.firsts);
        return (
          <li key={r.id} data-flip-id={r.id} className="grid gap-1">
            <span className="sr-only">
              {(
                labels?.row ??
                ((x) =>
                  `${x.label}: place ${x.place}, average place ${x.mean}, first for ${x.firsts} ${x.firsts === '1' ? 'person' : 'people'}`)
              )({ place: i + 1, label, mean, firsts })}
            </span>
            <div aria-hidden className={cn('flex items-baseline gap-3', stage ? 'text-lg' : 'text-sm')}>
              <span className="text-muted-foreground w-5 font-semibold tabular-nums">{i + 1}</span>
              <span className="min-w-0 flex-1 font-medium">{label}</span>
              <span className="text-muted-foreground tabular-nums">
                {(labels?.mean ?? ((m: string) => `avg ${m}`))(mean)}
              </span>
            </div>
            <span aria-hidden className={cn('bg-muted ms-8 block overflow-hidden rounded-full', stage ? 'h-3' : 'h-2')}>
              <span
                className="bg-primary block h-full origin-left rounded-full motion-safe:transition-transform motion-safe:duration-(--duration-slow) motion-safe:ease-move rtl:origin-right"
                style={{ transform: `scaleX(${r.points / top})` }}
              />
            </span>
          </li>
        );
      })}
    </FlipGroup>
  );
}
RankResults.displayName = 'RankResults';

export { RankChoices, RankResults };
export type { RankChoicesProps, RankChoicesLabels, RankResultsProps, RankResultsLabels, RankOption };

export type DayKey = string;

const DAY_MS = 86_400_000;
const KEY_RE = /^(\d{4})-(\d{2})-(\d{2})$/;

/**
 * The calendar day `date` falls on in `timeZone` (an IANA name such as
 * `"Europe/Paris"`). Without a time zone, the runtime's own is used, which on
 * a server is usually UTC: pass the player's zone when the page renders on
 * one.
 */
export function dayKey(date: Date | number = Date.now(), timeZone?: string): DayKey {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(typeof date === 'number' ? new Date(date) : date);
  const part = Object.fromEntries(parts.map((p) => [p.type, p.value]));
  return `${part.year}-${part.month}-${part.day}`;
}

/** True when `value` is a well-formed day key for a real date. */
export function isDayKey(value: unknown): value is DayKey {
  if (typeof value !== 'string') return false;
  const m = KEY_RE.exec(value);
  if (!m) return false;
  const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  return d.getUTCFullYear() === +m[1] && d.getUTCMonth() === +m[2] - 1 && d.getUTCDate() === +m[3];
}

function toUtc(key: DayKey): number {
  const m = KEY_RE.exec(key);
  if (!m) throw new RangeError(`Not a day key: "${key}" (expected YYYY-MM-DD)`);
  return Date.UTC(+m[1], +m[2] - 1, +m[3]);
}

/** Midnight UTC of the day, as a Date: the safe way to format a key with Intl. */
export function dayKeyToDate(key: DayKey): Date {
  return new Date(toUtc(key));
}

/** The key `days` after `key` (negative goes back). */
export function addDays(key: DayKey, days: number): DayKey {
  return new Date(toUtc(key) + days * DAY_MS).toISOString().slice(0, 10);
}

/** Whole days from `from` to `to`; negative when `to` is earlier. */
export function daysBetween(from: DayKey, to: DayKey): number {
  return Math.round((toUtc(to) - toUtc(from)) / DAY_MS);
}

/** Day of the week, 0 for Sunday to 6 for Saturday, as `Date.getDay` counts. */
export function weekdayOf(key: DayKey): number {
  return new Date(toUtc(key)).getUTCDay();
}

/**
 * The puzzle's number: 1 on `firstDay`, 2 the day after. Before `firstDay`
 * it is 0 or less, which a caller should treat as "not started".
 */
export function puzzleNumber(key: DayKey, firstDay: DayKey): number {
  return daysBetween(firstDay, key) + 1;
}

/** FNV-1a, 32-bit: a small, stable string hash for seeds. */
export function hashString(value: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < value.length; i++) {
    h ^= value.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/**
 * A seeded generator of numbers in [0, 1) (mulberry32). Good enough to deal
 * puzzles and shuffle answers the same way everywhere; not for anything
 * secret.
 */
export function seededRandom(seed: number | string): () => number {
  let a = typeof seed === 'string' ? hashString(seed) : seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4_294_967_296;
  };
}

/** A copy of `items` in a seeded order (Fisher–Yates). */
export function seededShuffle<T>(items: readonly T[], seed: number | string): T[] {
  const out = items.slice();
  const random = seededRandom(seed);
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [out[i], out[j]] = [out[j] as T, out[i] as T];
  }
  return out;
}

export interface DailyIndexOptions {
  /** The day puzzle 1 ran. */
  firstDay: DayKey;
  /** `sequence` walks the pool in order; `shuffle` deals it in a seeded order per cycle. @default 'sequence' */
  order?: 'sequence' | 'shuffle';
  /** Changes the shuffled order. @default 'daily' */
  seed?: string;
}

/**
 * Which item of a pool of `size` the day gets, or -1 for an empty pool or a
 * day before `firstDay`.
 */
export function dailyIndex(key: DayKey, size: number, options: DailyIndexOptions): number {
  const n = puzzleNumber(key, options.firstDay);
  if (size <= 0 || n < 1) return -1;
  const position = (n - 1) % size;
  if ((options.order ?? 'sequence') === 'sequence') return position;
  const cycle = Math.floor((n - 1) / size);
  const order = seededShuffle(
    Array.from({ length: size }, (_, i) => i),
    `${options.seed ?? 'daily'}:${cycle}`,
  );
  return order[position] as number;
}

/** The day's item from `pool`, or undefined when there is none. */
export function dailyItem<T>(pool: readonly T[], key: DayKey, options: DailyIndexOptions): T | undefined {
  const i = dailyIndex(key, pool.length, options);
  return i < 0 ? undefined : pool[i];
}

/**
 * Milliseconds until the next day starts in `timeZone`. On a day that a
 * clock change makes 23 or 25 hours long the answer can be off by that hour,
 * which is fine for a countdown and is why it is not used to pick puzzles.
 */
export function msUntilNextDay(now: Date | number = Date.now(), timeZone?: string): number {
  const date = typeof now === 'number' ? new Date(now) : now;
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(date);
  const part = Object.fromEntries(parts.map((p) => [p.type, Number(p.value)]));
  const elapsed =
    ((part.hour! * 60 + part.minute!) * 60 + part.second!) * 1000 + date.getMilliseconds();
  return DAY_MS - elapsed;
}

/**
 * @interlace/ui — games/daily
 *
 * The calendar under a daily game: which day it is for a player, which
 * puzzle that day gets, its number, and how long until the next one. Pure
 * functions, no React, no storage. Every component in `games/` builds on
 * these, and a server can call them too, so the puzzle a page renders and
 * the one a score is checked against come from the same arithmetic.
 *
 * ## Day keys
 *
 * A day is an ISO date string, `"2026-11-24"`, read in a time zone. Keys
 * sort as strings, survive JSON and storage unchanged, and compare without
 * a Date. Arithmetic on them runs in UTC, where every day has 24 hours, so
 * daylight-saving changes never skip or repeat a day.
 *
 * ## The puzzle of the day
 *
 * `dailyIndex` maps a day to an item in a pool. `order: 'sequence'` walks
 * the pool in order and starts again at the end. `order: 'shuffle'` deals
 * the pool in a seeded order that changes every cycle, and never repeats an
 * item inside a cycle. Both are deterministic: the same day, pool size and
 * seed give the same item on every device.
 */

/** An ISO calendar date, `YYYY-MM-DD`. */

import { seededShuffle } from '@/components/ui/games/daily';

/**
 * @interlace/ui — games/order-model
 *
 * Dealing and scoring for a put-them-in-order round: dates on a timeline,
 * sizes, rankings. Pure, so a server deals and scores the same round and a
 * share card can draw one mark per place without saying the answer.
 *
 * ## Two measures
 *
 * - `inPlace`: how many items sit exactly where they belong. Easy to say
 *   ("3 of 5 in the right place") and what the marks show.
 * - `pairs`: the share of all pairs the player put in the right relative
 *   order (1 − normalised Kendall distance). It is fairer than `inPlace`:
 *   one item dragged from the top to the bottom shifts every other item by
 *   one and zeroes `inPlace`, yet most pairs are still right. Points follow
 *   `pairs`.
 */

export interface OrderScoreOptions {
  /** Points for a perfect order. @default 100 */
  maxPoints?: number;
}

export interface OrderResult {
  /** The player's order, as ids. */
  order: string[];
  /** The right order, as ids. */
  correct: string[];
  /** One flag per place in the player's order: is that item in its right place? */
  places: boolean[];
  /** Items in their right place. */
  inPlace: number;
  /** Share of pairs in the right relative order, 0–1. */
  pairs: number;
  points: number;
  perfect: boolean;
}

function assertSameItems(order: readonly string[], correct: readonly string[]) {
  const a = [...order].sort();
  const b = [...correct].sort();
  if (new Set(correct).size !== correct.length) throw new RangeError('ids must be unique');
  if (a.length !== b.length || a.some((id, i) => id !== b[i])) {
    throw new RangeError('order must hold exactly the same ids as correct');
  }
}

/** Score the player's order against the right one. */
export function scoreOrder(order: readonly string[], correct: readonly string[], options: OrderScoreOptions = {}): OrderResult {
  assertSameItems(order, correct);
  const { maxPoints = 100 } = options;
  const rank = new Map(correct.map((id, i) => [id, i]));
  const places = order.map((id, i) => rank.get(id) === i);
  const n = order.length;
  let good = 0;
  let all = 0;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      all += 1;
      if ((rank.get(order[i] as string) as number) < (rank.get(order[j] as string) as number)) good += 1;
    }
  }
  const pairs = all === 0 ? 1 : good / all;
  const inPlace = places.filter(Boolean).length;
  return {
    order: [...order],
    correct: [...correct],
    places,
    inPlace,
    pairs,
    points: Math.round(maxPoints * pairs),
    perfect: inPlace === n,
  };
}

/**
 * A starting order for the round: seeded, so every player gets the same deal
 * on the same day, and never already solved (a round of two or more items
 * always starts with at least one item out of place).
 */
export function dealOrder(correct: readonly string[], seed: number | string): string[] {
  if (correct.length < 2) return [...correct];
  const out = seededShuffle(correct, seed);
  if (out.every((id, i) => id === correct[i])) out.push(out.shift() as string);
  return out;
}

/** `order` with the item at `from` moved to `to` (both clamped). */
export function moveItem<T>(order: readonly T[], from: number, to: number): T[] {
  const out = order.slice();
  if (from < 0 || from >= out.length) return out;
  const target = Math.min(out.length - 1, Math.max(0, to));
  const [item] = out.splice(from, 1);
  out.splice(target, 0, item as T);
  return out;
}

import { scoreOrder } from '@/components/ui/games/order-model';

/**
 * @interlace/ui — ranking-model
 *
 * A room ranks the same items by preference ("what would you want to see
 * first?"), with no right answer. `tallyRankings` turns everyone's order
 * into the room's: each item gets points by place (a Borda count: last
 * place 0, first place n − 1), its average place, and how many put it
 * first. `roomAgreement` says how much people agree with the room's order,
 * from 0 (the opposite) to 1 (the same), as the share of pairs in the same
 * order (see `scoreOrder` in `order-model`).
 *
 * A ranking that is not exactly the items, once each, is left out, so a bad
 * message cannot skew the room; each person counts once.
 */

export interface RankedItem {
  id: string;
  /** Borda points, summed over people. */
  points: number;
  /** Average place, 1 for first. */
  meanPlace: number;
  /** People who put it first. */
  firsts: number;
}

/** True when `order` holds every item exactly once. */
export function isFullRanking(order: readonly string[], items: readonly string[]): boolean {
  if (order.length !== items.length) return false;
  const set = new Set(order);
  return set.size === items.length && items.every((id) => set.has(id));
}

/**
 * The room's order, most preferred first. Ties go to more first places,
 * then to the items' given order. `meanPlace` is 0 when nobody has ranked.
 */
export function tallyRankings(
  rankings: Readonly<Record<string, readonly string[]>>,
  items: readonly string[],
): { items: RankedItem[]; people: number } {
  const n = items.length;
  const rows = new Map(items.map((id, i) => [id, { id, i, points: 0, places: 0, firsts: 0 }]));
  let people = 0;
  for (const order of Object.values(rankings)) {
    if (!isFullRanking(order, items)) continue;
    people++;
    order.forEach((id, place) => {
      const row = rows.get(id) as { points: number; places: number; firsts: number };
      row.points += n - 1 - place;
      row.places += place + 1;
      if (place === 0) row.firsts++;
    });
  }
  const ranked = [...rows.values()]
    .sort((a, b) => b.points - a.points || b.firsts - a.firsts || a.i - b.i)
    .map(({ id, points, places, firsts }) => ({
      id,
      points,
      firsts,
      meanPlace: people === 0 ? 0 : places / people,
    }));
  return { items: ranked, people };
}

/** How much the room agrees with its own order, 0 to 1; null with nobody. */
export function roomAgreement(
  rankings: Readonly<Record<string, readonly string[]>>,
  items: readonly string[],
): number | null {
  const valid = Object.values(rankings).filter((o) => isFullRanking(o, items));
  if (valid.length === 0) return null;
  const room = tallyRankings(rankings, items).items.map((r) => r.id);
  return valid.reduce((sum, o) => sum + scoreOrder(o, room).pairs, 0) / valid.length;
}
